# ===== BUTTON STYLE COMPATIBILITY =====
# Keep Telegram's blue/green/red button styles without replacing the
# InlineKeyboardButton class (replacing it breaks PTB internals/patches).
import inspect as _fnx_inspect
_FNX_ORIGINAL_INLINE_BUTTON = InlineKeyboardButton
try:
    _FNX_BUTTON_PARAMS = _fnx_inspect.signature(_FNX_ORIGINAL_INLINE_BUTTON).parameters
except Exception:
    _FNX_BUTTON_PARAMS = {}
_FNX_BUTTON_SUPPORTS_STYLE = "style" in _FNX_BUTTON_PARAMS
_FNX_BUTTON_SUPPORTS_API_KWARGS = "api_kwargs" in _FNX_BUTTON_PARAMS

def _fnx_button(*args, style=None, icon_custom_emoji_id=None, **kwargs):
    """Build a button safely on both old and new python-telegram-bot versions."""
    if _FNX_BUTTON_SUPPORTS_STYLE:
        if style is not None:
            kwargs["style"] = style
        if icon_custom_emoji_id is not None and "icon_custom_emoji_id" in _FNX_BUTTON_PARAMS:
            kwargs["icon_custom_emoji_id"] = icon_custom_emoji_id
        return _FNX_ORIGINAL_INLINE_BUTTON(*args, **kwargs)

    # Older PTB versions can forward unknown Bot API fields through api_kwargs.
    api_kwargs = dict(kwargs.pop("api_kwargs", None) or {})
    if style is not None:
        api_kwargs["style"] = style
    if icon_custom_emoji_id is not None:
        api_kwargs["icon_custom_emoji_id"] = icon_custom_emoji_id
    if api_kwargs and _FNX_BUTTON_SUPPORTS_API_KWARGS:
        kwargs["api_kwargs"] = api_kwargs
    # If even api_kwargs is unavailable, gracefully fall back to the normal
    # button rather than crashing /start and every callback.
    return _FNX_ORIGINAL_INLINE_BUTTON(*args, **kwargs)

# Keep the name used throughout the original bot, but DO NOT patch __init__.
InlineKeyboardButton = _fnx_button

