# ===== EMBEDDED START VIDEO =====
# The requested MP4 is embedded in this Python file, so no separate video file is required.
START_VIDEO_B64 = """"""

_START_VIDEO_PATH_CACHE = None

def get_start_video_path():
    """Extract embedded startup video once, then reuse the cached temp file."""
    global _START_VIDEO_PATH_CACHE
    if _START_VIDEO_PATH_CACHE and os.path.isfile(_START_VIDEO_PATH_CACHE):
        return _START_VIDEO_PATH_CACHE
    path = os.path.join(tempfile.gettempdir(), "finxzx_start.mp4")
    # Avoid repeatedly decoding the 4.8 MB script payload on every /start.
    if not os.path.isfile(path) or os.path.getsize(path) == 0:
        data = zlib.decompress(base64.b64decode(START_VIDEO_B64))
        with open(path, "wb") as f:
            f.write(data)
    _START_VIDEO_PATH_CACHE = path
    return path
