def _premiumize_html(text):
    """Turn mapped Unicode emojis into real Telegram custom-emoji HTML tags."""
    if not text:
        return text
    text = str(text)
    protected = []

    def protect(match):
        protected.append(match.group(0))
        return f"\x00PEMOJI{len(protected)-1}\x00"

    text = re.sub(r'<tg-emoji\b[^>]*>.*?</tg-emoji>', protect, text, flags=re.S | re.I)
    text = re.sub(r'<(?:code|pre)\b[^>]*>.*?</(?:code|pre)>', protect, text, flags=re.S | re.I)

    for emoji, cid in PREMIUM_EMOJI_MAP.items():
        if emoji in text:
            text = text.replace(emoji, f'<tg-emoji emoji-id="{cid}">{emoji}</tg-emoji>')

    for i, value in enumerate(protected):
        text = text.replace(f"\x00PEMOJI{i}\x00", value)
    return text


def _markdown_to_safe_html(text):
    """Small safe Markdown -> HTML converter for this bot's simple legacy Markdown messages."""
    text = str(text)
    protected = []

    def protect_value(value):
        protected.append(value)
        return f"\x00PMARK{len(protected)-1}\x00"

    text = re.sub(
        r'```(?:\w+)?\n?(.*?)```',
        lambda m: protect_value(f"<pre>{html.escape(m.group(1), quote=False)}</pre>"),
        text,
        flags=re.S,
    )
    text = re.sub(
        r'`([^`\n]+)`',
        lambda m: protect_value(f"<code>{html.escape(m.group(1), quote=False)}</code>"),
        text,
    )
    text = re.sub(
        r'\[([^\]]+)\]\(([^)]+)\)',
        lambda m: protect_value(
            f'<a href="{html.escape(m.group(2), quote=True)}">{html.escape(m.group(1), quote=False)}</a>'
        ),
        text,
    )

    text = html.escape(text, quote=False)
    text = re.sub(r'\*\*(.+?)\*\*', r'<b>\1</b>', text)
    text = re.sub(r'\*([^*\n]+)\*', r'<b>\1</b>', text)
    text = re.sub(r'_([^_\n]+)_', r'<i>\1</i>', text)

    for i, value in enumerate(protected):
        text = text.replace(f"\x00PMARK{i}\x00", value)
    return text


def _prepare_premium_text(text, parse_mode=None):
    if not isinstance(text, str):
        return text, parse_mode

    if parse_mode and str(parse_mode).upper() == "HTML":
        return _premiumize_html(text), parse_mode

    if parse_mode and str(parse_mode).upper() == "MARKDOWN":
        text = _markdown_to_safe_html(text)
        return _premiumize_html(text), "HTML"

    safe = html.escape(text, quote=False)
    if not any(e in text for e in PREMIUM_EMOJI_MAP):
        safe = "✨ " + safe
    return _premiumize_html(safe), "HTML"


def _install_premium_output_patch():
    # Re-import Telegram classes locally so this engine never fails with
    # NameError even when the host app executes this file through exec().
    from telegram import Bot, Message, CallbackQuery, InlineKeyboardButton
    from telegram.error import BadRequest

    if getattr(Bot, "_fnx_premium_output_patch", False):
        return

    original_send_message = Bot.send_message
    async def patched_send_message(self, *args, **kwargs):
        original_parse = kwargs.get("parse_mode")
        if "text" in kwargs and isinstance(kwargs["text"], str):
            original_text = kwargs["text"]
            kwargs["text"], kwargs["parse_mode"] = _prepare_premium_text(original_text, original_parse)
            try:
                return await original_send_message(self, *args, **kwargs)
            except BadRequest:
                kwargs["text"] = original_text
                if original_parse is None:
                    kwargs.pop("parse_mode", None)
                else:
                    kwargs["parse_mode"] = original_parse
                return await original_send_message(self, *args, **kwargs)
        return await original_send_message(self, *args, **kwargs)
    Bot.send_message = patched_send_message

    original_reply_text = Message.reply_text
    async def patched_reply_text(self, *args, **kwargs):
        original_parse = kwargs.get("parse_mode")
        if args and isinstance(args[0], str):
            original_text = args[0]
            new_text, new_mode = _prepare_premium_text(original_text, original_parse)
            args = list(args)
            args[0] = new_text
            args = tuple(args)
            kwargs["parse_mode"] = new_mode
            try:
                return await original_reply_text(self, *args, **kwargs)
            except BadRequest:
                args = list(args)
                args[0] = original_text
                args = tuple(args)
                if original_parse is None:
                    kwargs.pop("parse_mode", None)
                else:
                    kwargs["parse_mode"] = original_parse
                return await original_reply_text(self, *args, **kwargs)
        return await original_reply_text(self, *args, **kwargs)
    Message.reply_text = patched_reply_text

    original_edit_message_text = CallbackQuery.edit_message_text
    async def patched_edit_message_text(self, *args, **kwargs):
        original_parse = kwargs.get("parse_mode")
        if args and isinstance(args[0], str):
            original_text = args[0]
            new_text, new_mode = _prepare_premium_text(original_text, original_parse)
            args = list(args)
            args[0] = new_text
            args = tuple(args)
            kwargs["parse_mode"] = new_mode
            try:
                return await original_edit_message_text(self, *args, **kwargs)
            except BadRequest:
                args = list(args)
                args[0] = original_text
                args = tuple(args)
                if original_parse is None:
                    kwargs.pop("parse_mode", None)
                else:
                    kwargs["parse_mode"] = original_parse
                return await original_edit_message_text(self, *args, **kwargs)
        return await original_edit_message_text(self, *args, **kwargs)
    CallbackQuery.edit_message_text = patched_edit_message_text

    original_send_video = Bot.send_video
    async def patched_send_video(self, *args, **kwargs):
        original_parse = kwargs.get("parse_mode")
        if "caption" in kwargs and isinstance(kwargs["caption"], str):
            original_caption = kwargs["caption"]
            new_caption, new_mode = _prepare_premium_text(original_caption, original_parse)
            kwargs["caption"] = new_caption
            kwargs["parse_mode"] = new_mode
            try:
                return await original_send_video(self, *args, **kwargs)
            except BadRequest:
                kwargs["caption"] = original_caption
                if original_parse is None:
                    kwargs.pop("parse_mode", None)
                else:
                    kwargs["parse_mode"] = original_parse
                return await original_send_video(self, *args, **kwargs)
        return await original_send_video(self, *args, **kwargs)
    Bot.send_video = patched_send_video

    original_edit_caption = Message.edit_caption
    async def patched_edit_caption(self, *args, **kwargs):
        original_parse = kwargs.get("parse_mode")
        if args and isinstance(args[0], str):
            original_caption = args[0]
            new_caption, new_mode = _prepare_premium_text(original_caption, original_parse)
            args = list(args)
            args[0] = new_caption
            args = tuple(args)
            kwargs["parse_mode"] = new_mode
            try:
                return await original_edit_caption(self, *args, **kwargs)
            except BadRequest:
                args = list(args)
                args[0] = original_caption
                args = tuple(args)
                if original_parse is None:
                    kwargs.pop("parse_mode", None)
                else:
                    kwargs["parse_mode"] = original_parse
                return await original_edit_caption(self, *args, **kwargs)
        return await original_edit_caption(self, *args, **kwargs)
    Message.edit_caption = patched_edit_caption

    # Do NOT monkeypatch InlineKeyboardButton.__init__.
    # Some hosts run an older PTB where style/icon fields are exposed through
    # api_kwargs; monkeypatching __init__ breaks every button at /start.

    Bot._fnx_premium_output_patch = True


_install_premium_output_patch()
