def bold(text):
    m = {'a':'𝐚','b':'𝐛','c':'𝐜','d':'𝐝','e':'𝐞','f':'𝐟','g':'𝐠','h':'𝐡','i':'𝐢','j':'𝐣','k':'𝐤','l':'𝐥','m':'𝐦','n':'𝐧','o':'𝐨','p':'𝐩','q':'𝐪','r':'𝐫','s':'𝐬','t':'𝐭','u':'𝐮','v':'𝐯','w':'𝐰','x':'𝐱','y':'𝐲','z':'𝐳','A':'𝐀','B':'𝐁','C':'𝐂','D':'𝐃','E':'𝐄','F':'𝐅','G':'𝐆','H':'𝐇','I':'𝐈','J':'𝐉','K':'𝐊','L':'𝐋','M':'𝐌','N':'𝐍','O':'𝐎','P':'𝐏','Q':'𝐐','R':'𝐑','S':'𝐒','T':'𝐓','U':'𝐔','V':'𝐕','W':'𝐖','X':'𝐗','Y':'𝐘','Z':'𝐙','0':'𝟎','1':'𝟏','2':'𝟐','3':'𝟑','4':'𝟒','5':'𝟓','6':'𝟔','7':'𝟕','8':'𝟖','9':'𝟗'}
    return ''.join(m.get(c, c) for c in text)

def parse_amount(args, user_balance=None):
    if not args: return None
    arg = args[0].lower().strip()
    if arg in ["all", "max", "sab", "sara"]:
        return user_balance if user_balance and user_balance > 0 else None
    if arg in ["half", "aadha", "50%"]:
        return (user_balance // 2) if user_balance and user_balance > 0 else None
    if arg in ["quarter", "25%", "chauthai"]:
        return (user_balance // 4) if user_balance and user_balance > 0 else None
    multiplier = 1
    if arg.endswith("k"): multiplier = 1_000; arg = arg[:-1]
    elif arg.endswith("m"): multiplier = 1_000_000; arg = arg[:-1]
    elif arg.endswith("b"): multiplier = 1_000_000_000; arg = arg[:-1]
    elif arg.endswith("t"): multiplier = 1_000_000_000_000; arg = arg[:-1]
    try:
        amount = int(float(arg) * multiplier)
        return amount if amount > 0 else None
    except: return None

def _default_db():
    return {
        "users": {},
        "banned": [],
        "loans": {},
        "rps_games": {},
        "ttt_games": {},
        "loan_games": {},
        "redeem_codes": {},
        "premium_requests": {},
        "trivia_stats": {},
    }

def _normalise_db(data):
    default = _default_db()
    if not isinstance(data, dict):
        return default
    for k, v in default.items():
        if not isinstance(data.get(k), type(v)):
            data[k] = v
    return data

def load_db():
    """Load the bot state from the new real SQLite database."""
    default = _default_db()
    try:
        conn = sqlite3.connect(DB_FILE, timeout=15)
        conn.execute("CREATE TABLE IF NOT EXISTS bot_state (id INTEGER PRIMARY KEY CHECK (id = 1), data TEXT NOT NULL)")
        row = conn.execute("SELECT data FROM bot_state WHERE id = 1").fetchone()
        if row is None:
            # If the old JSON backup is placed beside this script, import it once
            # into SQLite only when SQLite is empty. The JSON file is left untouched.
            legacy_path = os.path.join(BASE_DIR, "neha_data.json")
            data = default
            if os.path.isfile(legacy_path):
                try:
                    with open(legacy_path, "r", encoding="utf-8") as legacy_file:
                        legacy_data = json.load(legacy_file)
                    if isinstance(legacy_data, dict) and isinstance(legacy_data.get("users"), dict):
                        data = _normalise_db(legacy_data)
                except Exception as legacy_error:
                    print(f"Legacy JSON import skipped: {legacy_error}")
            conn.execute("INSERT INTO bot_state (id, data) VALUES (1, ?)", (json.dumps(data, ensure_ascii=False),))
            conn.commit()
            conn.close()
            return data
        data = _normalise_db(json.loads(row[0]))
        conn.close()
        return data
    except Exception as e:
        print(f"DB load error: {e}")
        return default

def save_db():
    """Atomically save the current bot state into SQLite."""
    try:
        payload = json.dumps(db, ensure_ascii=False, separators=(",", ":"))
        conn = sqlite3.connect(DB_FILE, timeout=15)
        conn.execute("CREATE TABLE IF NOT EXISTS bot_state (id INTEGER PRIMARY KEY CHECK (id = 1), data TEXT NOT NULL)")
        conn.execute("INSERT INTO bot_state (id, data) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET data=excluded.data", (payload,))
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"DB save error: {e}")

db = load_db()

def get_user(user_id):
    uid = str(user_id)
    if not isinstance(db.get("users"), dict): db["users"] = {}
    if uid not in db["users"]:
        db["users"][uid] = {"name": "User", "balance": 100, "kills": 0, "deaths": 0, "robbed": 0, "protected_until": 0, "daily_claimed": 0, "wins": 0, "losses": 0, "inventory": [], "is_dead": False, "ledger": [], "bank": 0, "bank_interest_at": 0, "properties": [], "premium_until": 0, "mission_day": 0, "mission_progress": {}, "mission_claimed": [], "work_at": 0, "spin_at": 0, "streak": 0}
        save_db()
    user = db["users"][uid]
    if not isinstance(user, dict):
        user = {"name": "User", "balance": 100, "kills": 0, "deaths": 0, "robbed": 0, "protected_until": 0, "daily_claimed": 0, "wins": 0, "losses": 0, "inventory": [], "is_dead": False, "ledger": [], "bank": 0, "bank_interest_at": 0, "properties": [], "premium_until": 0, "mission_day": 0, "mission_progress": {}, "mission_claimed": [], "work_at": 0, "spin_at": 0, "streak": 0}
        db["users"][uid] = user
    defaults = {"name": "User", "balance": 100, "kills": 0, "deaths": 0, "robbed": 0, "protected_until": 0, "daily_claimed": 0, "wins": 0, "losses": 0, "inventory": [], "is_dead": False, "ledger": [], "bank": 0, "bank_interest_at": 0, "properties": [], "premium_until": 0, "mission_day": 0, "mission_progress": {}, "mission_claimed": [], "work_at": 0, "spin_at": 0, "streak": 0}
    for k, v in defaults.items():
        if k not in user: user[k] = v
    return user

BANK_RATE = 0.05
BANK_PERIOD = 48 * 60 * 60


def parse_money_amount(raw, available):
    """Parse exact amount, K/M/B suffixes, or fractions of available funds."""
    token = str(raw).strip().lower().replace(",", "")
    base = Decimal(str(max(0, available)))
    aliases = {"all": Decimal("1"), "half": Decimal("0.5"), "1/2": Decimal("0.5"),
               "quarter": Decimal("0.25"), "1/4": Decimal("0.25"),
               "halfquarter": Decimal("0.125"), "eighth": Decimal("0.125"), "1/8": Decimal("0.125")}
    if token in aliases:
        value = base * aliases[token]
    else:
        m = re.fullmatch(r"(\d+(?:\.\d+)?)([kmb]?)", token)
        if not m:
            raise ValueError("Amount format: 1k, 2m, 100b, all, half, quarter, halfquarter")
        value = Decimal(m.group(1)) * {"": Decimal(1), "k": Decimal(1000), "m": Decimal(1000000), "b": Decimal(1000000000)}[m.group(2)]
    value = value.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
    if value <= 0:
        raise ValueError("Amount 0 se zyada hona chahiye.")
    return value


def property_kind(entry):
    if isinstance(entry, dict):
        return str(entry.get("catalog_id", entry.get("id", ""))).split("#", 1)[0]
    return str(entry)

def property_matches(entry, requested):
    if isinstance(entry, dict):
        return str(entry.get("id", "")).lower() == requested or property_kind(entry).lower() == requested
    return str(entry).lower() == requested

def _apply_bank_interest(user_id):
    """Apply compounded 5% bank interest for every completed 48h period."""
    data = get_user(user_id)
    bank = float(data.get("bank", 0) or 0)
    now = time.time()
    last = float(data.get("bank_interest_at", 0) or 0)
    if bank <= 0:
        data["bank_interest_at"] = now
        return 0
    if last <= 0:
        data["bank_interest_at"] = now
        save_db()
        return 0
    periods = int((now - last) // BANK_PERIOD)
    if periods <= 0:
        return 0
    old_bank = bank
    for _ in range(periods):
        bank *= (1 + BANK_RATE)
    data["bank"] = round(bank, 2)
    data["bank_interest_at"] = last + periods * BANK_PERIOD
    save_db()
    return round(bank - old_bank, 2)


def _find_user_for_owner(identifier):
    """Resolve owner-only /bank lookup by reply, numeric ID or @username."""
    if not identifier:
        return None, None
    ident = str(identifier).strip()
    if ident.isdigit():
        uid = ident
        if uid in db.get("users", {}):
            return uid, db["users"][uid]
    wanted = ident.lstrip("@").lower()
    for uid, data in db.get("users", {}).items():
        uname = str(data.get("username", "")).lstrip("@").lower()
        if uname and uname == wanted:
            return uid, data
    return None, None


async def bank(update, context):
    """Personal bank. Normal users can only view/modify their own bank.
    Owner may inspect another user by replying, ID, or @username.
    """
    if not update.message:
        return
    user = update.effective_user
    me = get_user(user.id)

    # Keep username/name in our local record for owner lookups.
    me["name"] = user.first_name or "User"
    me["username"] = user.username or ""
    save_db()

    args = list(context.args or [])
    target_uid = str(user.id)
    target = me
    owner_lookup = False

    # Owner can inspect another user's bank only.
    if is_owner(user.id):
        if update.message.reply_to_message:
            target_user = update.message.reply_to_message.from_user
            target_uid = str(target_user.id)
            target = get_user(target_user.id)
            target["name"] = target_user.first_name or target.get("name", "User")
            target["username"] = target_user.username or target.get("username", "")
            owner_lookup = True
        elif args and args[0].lower() not in {"deposit", "withdraw"}:
            uid, found = _find_user_for_owner(args[0])
            if found is None:
                await update.message.reply_text("❌ User nahi mila. ID/@username ya user ko reply karke /bank bhejo.")
                return
            target_uid, target = uid, found
            owner_lookup = True

    # Normal users cannot inspect another user's bank.
    if not is_owner(user.id) and args and args[0].lower() not in {"deposit", "withdraw"}:
        await update.message.reply_text("🔒 Aap sirf apna bank dekh sakte ho.\nUse: /bank")
        return

    action = args[0].lower() if args else "view"
    if action in {"deposit", "withdraw"}:
        if len(args) != 2:
            await update.message.reply_text(
                f"🏦 <b>BANK</b>\n\nUse:\n<code>/bank deposit AMT</code>\n<code>/bank withdraw AMT</code>\nAmounts: all, half, quarter, halfquarter, 1k, 2m, 100b",
                parse_mode="HTML")
            return
        _apply_bank_interest(user.id)
        me = get_user(user.id)
        wallet = Decimal(str(me.get("balance", 0) or 0))
        bank_balance = Decimal(str(me.get("bank", 0) or 0))
        available = wallet if action == "deposit" else bank_balance
        try:
            amount_dec = parse_money_amount(args[1], available)
        except (ValueError, InvalidOperation) as exc:
            await update.message.reply_text(f"❌ {exc}\nExamples: <code>1k</code>, <code>2m</code>, <code>100b</code>, <code>all</code>, <code>half</code>, <code>quarter</code>, <code>halfquarter</code>", parse_mode="HTML")
            return
        amount = float(amount_dec)

        if action == "deposit":
            if amount_dec > wallet:
                await update.message.reply_text(f"❌ Wallet me sirf <b>${wallet:,.2f}</b> hai.", parse_mode="HTML")
                return
            me["balance"] = float(wallet - amount_dec)
            me["bank"] = float(bank_balance + amount_dec)
            if not me.get("bank_interest_at"):
                me["bank_interest_at"] = time.time()
            add_to_ledger(user.id, -amount, "Bank Deposit", f"Deposited ${amount:,.2f} to bank", wallet, me["balance"])
            save_db()
            await update.message.reply_text(
                f"🏦 <b>BANK DEPOSIT</b>\n━━━━━━━━━━━━\n\n💵 Deposited: <b>${amount:,.2f}</b>\n🏦 Bank: <b>${me['bank']:,.2f}</b>\n👛 Wallet: <b>${me['balance']:,.2f}</b>",
                parse_mode="HTML")
            return

        if amount_dec > bank_balance:
            await update.message.reply_text(f"❌ Bank me sirf <b>${bank_balance:,.2f}</b> hai.", parse_mode="HTML")
            return
        me["bank"] = float(max(Decimal("0"), bank_balance - amount_dec))
        me["balance"] = float(wallet + amount_dec)
        if me["bank"] <= 0:
            me["bank_interest_at"] = time.time()
        add_to_ledger(user.id, amount, "Bank Withdraw", f"Withdrew ${amount:,.2f} from bank", wallet, me["balance"])
        save_db()
        await update.message.reply_text(
            f"🏦 <b>BANK WITHDRAW</b>\n━━━━━━━━━━━━\n\n💵 Withdrawn: <b>${amount:,.2f}</b>\n🏦 Bank: <b>${me['bank']:,.2f}</b>\n👛 Wallet: <b>${me['balance']:,.2f}</b>",
            parse_mode="HTML")
        return

    _apply_bank_interest(int(target_uid))
    target = get_user(int(target_uid))
    bank_balance = float(target.get("bank", 0) or 0)
    wallet = float(target.get("balance", 0) or 0)
    name = target.get("name", "User")
    username = target.get("username", "")
    extra = f"\n👤 ᴜꜱᴇʀ: {name}" if owner_lookup else ""
    if owner_lookup and username:
        extra += f" (@{username.lstrip('@')})"
    text = (
        f"🏦 <b>ʙᴀɴᴋ</b>\n"
        f"━━━━━━━━━━━━\n\n"
        f"👛 ᴡᴀʟʟᴇᴛ: <b>${wallet:,.2f}</b>\n"
        f"🏦 ʙᴀɴᴋ: <b>${bank_balance:,.2f}</b>\n"
        f"📈 ʀᴀᴛᴇ: <b>𝟓% ᴇᴠᴇʀʏ 𝟒𝟖ʜ</b>"
        f"{extra}\n\n"
        f"<code>/bank deposit [amt]</code>\n"
        f"<code>/bank withdraw [amt]</code>"
    )
    await update.message.reply_text(text, parse_mode="HTML")

def add_to_ledger(user_id, amount, action, detail, old_balance, new_balance):
    uid = str(user_id)
    get_user(uid)
    now = time.time()
    if "ledger" not in db["users"][uid]: db["users"][uid]["ledger"] = []
    
    db["users"][uid]["ledger"].append({
        "amount": amount,
        "action": action,
        "detail": detail,
        "old_balance": old_balance,
        "new_balance": new_balance,
        "timestamp": now
    })
    
    db["users"][uid]["ledger"] = [x for x in db["users"][uid]["ledger"] if now - x["timestamp"] < 86400]
    save_db()

def is_owner(user_id):
    try:
        return int(user_id) == int(OWNER_ID)
    except (TypeError, ValueError):
        return False

def is_admin(user_id):
    """Accept numeric admin IDs whether SQLite/JSON stored them as ints or strings."""
    if is_owner(user_id):
        return True
    try:
        wanted = str(int(user_id))
        admins = db.get("admins", [])
        if isinstance(admins, dict):
            admins = admins.keys()
        return any(str(int(item)) == wanted for item in admins)
    except (TypeError, ValueError):
        return False
def is_banned(user_id):
    if not isinstance(db.get("banned"), list): db["banned"] = []
    return str(user_id) in db["banned"]
def get_rank(user_id):
    if not isinstance(db.get("users"), dict): return "N/A"
    users = sorted(db["users"].items(), key=lambda x: x[1].get("balance", 0), reverse=True)
    for i, (uid, _) in enumerate(users):
        if uid == str(user_id): return i + 1
    return "N/A"
def medal(rank): return {1: "🥇", 2: "🥈", 3: "🥉"}.get(rank, f"{rank}.")

def get_mention(user):
    if user.username:
        return f"@{user.username}"
    name = user.first_name or "User"
    for ch in ['[', ']', '(', ')', '_', '*', '`', '~', '>', '#', '+', '-', '=', '|', '{', '}', '.', '!', '\\']:
        name = name.replace(ch, '')
    if not name.strip(): name = "User"
    return f"[{name}](tg://user?id={user.id})"

