async def _show_callback_content(query, text, reply_markup=None):
    """Safely show text from an inline button on text OR media messages.
    Some Telegram messages have no editable text/caption, so fall back to
    sending a new message instead of failing with 'There is no text to edit'.
    """
    if not query or not query.message:
        return

    # First try a normal text edit when the message actually has text.
    try:
        if getattr(query.message, "text", None):
            await query.edit_message_text(text=text, reply_markup=reply_markup)
            return
    except Exception:
        pass

    # Then try editing a media caption (video/photo/document/etc.).
    try:
        if getattr(query.message, "caption", None) is not None or getattr(query.message, "video", None) or getattr(query.message, "photo", None) or getattr(query.message, "document", None):
            await query.edit_message_caption(caption=text, reply_markup=reply_markup)
            return
    except Exception:
        pass

    # Final fallback: always send the requested Help screen as a new message.
    try:
        await query.message.reply_text(text, reply_markup=reply_markup)
    except Exception as e:
        print(f"Help display fallback error: {e}")

