async def shop_buy_callback(update, context):
    query = update.callback_query
    item_id = query.data.replace("shop_buy_", "")
    item = SHOP_ITEMS.get(item_id)
    
    user_id = query.from_user.id
    get_user(user_id)
    wallet = db["users"][str(user_id)]["balance"]
    
    if wallet >= item['price']:
        old_bal = db["users"][str(user_id)]["balance"]
        db["users"][str(user_id)]["balance"] -= item['price']
        new_bal = db["users"][str(user_id)]["balance"]
        
        if "inventory" not in db["users"][str(user_id)]: db["users"][str(user_id)]["inventory"] = []
        db["users"][str(user_id)]["inventory"].append(item_id)
        
        add_to_ledger(user_id, -item['price'], "Shop", f"Bought {item['name']}", old_bal, new_bal)
        
        save_db()
        popup_text = f"𝐍𝖊𝖍𝖆𝖆\n\n🎉 BOUGHT {item['name'].upper()}!"
        await query.answer(text=popup_text, show_alert=True)
    else:
        await query.answer(text="𝐍𝖊𝖍𝖆𝖆\n\n❌ YOU DON'T HAVE ENOUGH MONEY!", show_alert=True)

