async def property_buy_callback(update, context):
    query = update.callback_query
    pid = query.data.replace("property_buy_", "", 1)
    prop = PROPERTY_ITEMS.get(pid)
    if not prop:
        await query.answer("Property not found.", show_alert=True)
        return

    data = get_user(query.from_user.id)
    price = int(prop["price"])
    balance = int(data.get("balance", 0))
    if balance < price:
        await query.answer("❌ Wallet balance is not enough.", show_alert=True)
        return

    old_bal = balance
    data["balance"] = balance - price
    instance_id = f"{pid}#{int(time.time() * 1000)}#{random.randint(100,999)}"
    data.setdefault("properties", []).append({
        "id": instance_id,
        "catalog_id": pid,
        "bought_at": time.time(),
        "purchase_price": price,
    })
    add_to_ledger(query.from_user.id, -price, "Property Purchase", f"Bought {prop['name']}", old_bal, data["balance"])
    save_db()

    wallet_now = data["balance"]
    text = (
        f"✅ 🏡 𝐏𝐑𝐎𝐏𝐄𝐑𝐓𝐘 𝐏𝐔𝐑𝐂𝐇𝐀𝐒𝐄𝐃!\n"
        f"━━━━━━━━━━━━\n"
        f"🏠 Property: {prop['name']}\n"
        f"💸 Paid: ${price:,}\n"
        f"👛 Wallet Left: ${wallet_now:,}\n"
        f"⏳ 48 hours ke baad resale par 105% milega.\n"
        f"🪪 Property ID: {instance_id}\n\n"
        f"/mypropertys se apni properties dekho."
    )
    keyboard = [[InlineKeyboardButton("🏡 My Properties", callback_data="property_myproperties")],
                [InlineKeyboardButton("🛍️ Back to Properties", callback_data="property_page_0", style="success")]]
    await query.answer("🏡 Purchase successful!", show_alert=True)
    try:
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
    except BadRequest:
        pass

