async def mypropertys_cmd(update, context):
    if not update.message:
        return
    data = get_user(update.effective_user.id)
    owned = data.get("properties", [])
    if not owned:
        await update.message.reply_text("🏡 Abhi aapke paas koi property nahi hai. /shop se property khareedo.")
        return
    lines = ["🏡 𝐌𝐘 𝐏𝐑𝐎𝐏𝐄𝐑𝐓𝐈𝐄𝐒\n━━━━━━━━━━━━"]
    for idx, entry in enumerate(owned, 1):
        pid = entry.get("id") if isinstance(entry, dict) else entry
        prop = PROPERTY_ITEMS.get(property_kind(entry), {"name": str(pid), "price": 0})
        bought = entry.get("bought_at", time.time()) if isinstance(entry, dict) else time.time()
        hours = max(0, int((time.time() - bought) // 3600))
        lines.append(f"\n{idx}. {prop['name']}\n🆔 ID: <code>{pid}</code> · Held: {hours}h")
    lines.append("\n\n💡 Sell: <code>/sellproperty ITEM_ID</code> · Gift: reply to user with <code>/giftproperty ITEM_ID</code>")
    await update.message.reply_text("".join(lines), parse_mode="HTML")

async def sellproperty_cmd(update, context):
    if not update.message:
        return
    data = get_user(update.effective_user.id)
    if not context.args:
        await update.message.reply_text("🏡 Use: /sellproperty ITEM_ID\nCheck IDs with /mypropertys")
        return
    pid = context.args[0].lower()
    owned = data.setdefault("properties", [])
    index = next((i for i, entry in enumerate(owned) if property_matches(entry, pid)), None)
    if index is None:
        await update.message.reply_text("❌ Ye property aapki nahi hai. /mypropertys check karo.")
        return
    entry = owned[index]
    kind = property_kind(entry)
    prop = PROPERTY_ITEMS.get(kind, {"name": kind, "price": int(entry.get("purchase_price", 0)) if isinstance(entry, dict) else 0})
    purchase_price = int(entry.get("purchase_price", prop["price"])) if isinstance(entry, dict) else prop["price"]
    bought_at = float(entry.get("bought_at", time.time())) if isinstance(entry, dict) else time.time()
    held_48h = time.time() - bought_at >= PROPERTY_HOLD_SECONDS
    payout = int(purchase_price * (1.05 if held_48h else 0.90))
    old_bal = data["balance"]
    owned.pop(index)
    data["balance"] += payout
    add_to_ledger(update.effective_user.id, payout, "Property Sale", f"Sold {prop['name']}", old_bal, data["balance"])
    save_db()
    note = "5% extra profit after 48h" if held_48h else "10% early-sale deduction"
    await update.message.reply_text(f"🏡 Sold {prop['name']} for ${payout:,}.\n✨ {note}\n👛 Wallet: ${data['balance']:,}")

async def giftproperty_cmd(update, context):
    if not update.message:
        return
    if not update.message.reply_to_message:
        await update.message.reply_text("🎁 Kisi user ke message par reply karke use karo: /giftproperty ITEM_ID")
        return
    if not context.args:
        await update.message.reply_text("🏡 Property ID do. IDs dekhne ke liye /mypropertys")
        return
    sender = update.effective_user
    target = update.message.reply_to_message.from_user
    if target.is_bot or target.id == sender.id:
        await update.message.reply_text("❌ Apne aap ko ya bot ko property gift nahi kar sakte.")
        return
    pid = context.args[0].lower()
    sender_data = get_user(sender.id)
    target_data = get_user(target.id)
    owned = sender_data.setdefault("properties", [])
    index = next((i for i, entry in enumerate(owned) if property_matches(entry, pid)), None)
    if index is None:
        await update.message.reply_text("❌ Ye property aapki nahi hai.")
        return
    entry = owned.pop(index)
    if not isinstance(entry, dict):
        entry = {"id": pid, "purchase_price": PROPERTY_ITEMS.get(pid, {}).get("price", 0)}
    entry["bought_at"] = time.time()  # 48-hour holding clock restarts for recipient
    target_data.setdefault("properties", []).append(entry)
    save_db()
    prop_name = PROPERTY_ITEMS.get(property_kind(entry), {"name": pid})["name"]
    await update.message.reply_text(f"🎁 {prop_name} successfully gifted to {target.first_name}! 🏡")

