async def notify_owner_new_user(context, user, source_chat=None):
    """Notify the owner once when a genuinely new user first appears.

    The notification is intentionally kept close to the reference screenshot:
    NEW USER JOINED + name + username + numeric Telegram user ID.
    """
    try:
        username = f"@{user.username}" if user.username else "—"
        name = user.first_name or "User"
        source_line = ""
        if source_chat is not None:
            try:
                chat_title = source_chat.title or "Group"
                source_line = f"\n\n📍 GROUP: {chat_title}"
            except Exception:
                pass
        text = (
            "🎁 <b>NEW USER JOINED</b>\n"
            "━━━━━━━━━━━━━━━━━━━━\n\n"
            f"👤 <b>NAME:</b> {name}\n"
            f"🔗 <b>USERNAME:</b> {username}\n"
            f"👑 <b>USER ID:</b> <code>{user.id}</code>"
            f"{source_line}"
        )
        await context.bot.send_message(chat_id=OWNER_ID, text=text, parse_mode="HTML")
    except Exception as e:
        print(f"Owner new-user notification error: {e}")

async def start(update, context):
    if not update.message:
        return

    user = update.effective_user
    # Ignore accidental rapid duplicate /start messages.
    now = time.monotonic()
    last_start = context.user_data.get("_fnx_last_start", 0.0)
    if now - last_start < START_COOLDOWN_SECONDS:
        return
    context.user_data["_fnx_last_start"] = now

    start_data = get_user(user.id)
    start_data["name"] = user.first_name or "User"
    start_data["username"] = user.username or ""
    save_db()
    if is_banned(user.id):
        await update.message.reply_text("🚫 " + sc("you are banned"))
        return

    # ONE /start = ONE Telegram message:
    # video + complete welcome text + buttons are sent together.
    try:
        video_path = get_start_video_path()
        caption = welcome_text(user)
        with open(video_path, "rb") as video_file:
            await update.message.reply_video(
                video=video_file,
                caption=caption,
                reply_markup=start_keyboard(),
            )
    except Exception as e:
        print(f"Start video error: {e}")
        # If video sending fails, still send exactly one welcome message.
        await update.message.reply_text(
            welcome_text(user),
            reply_markup=start_keyboard(),
        )

