async def bal(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
        get_user(target.id)
        data = db["users"][str(target.id)]
        name = target.first_name
        uid = target.id
    else:
        data = db["users"][str(user.id)]
        name = user.first_name
        uid = user.id

    status_text = "ᴅᴇᴀᴅ" if data.get("is_dead", False) else "ᴀʟɪᴠᴇ"
    protect_status = "ɴᴏɴᴇ"
    if data.get("protected_until", 0) > time.time():
        protect_status = "ʏᴇꜱ"

    text = (
        f"🌸 {name}\n"
        f"💰 ${data['balance']:,} | 🏆 #{get_rank(uid)}\n"
        f"💗 💗 {status_text} | ⚔️ {data['kills']} ᴋɪʟʟꜱ\n\n"
        f"🎁 ᴀᴄᴛɪᴠᴇ :\n"
        f"⚔️ ᴩʀᴏᴛᴇᴄᴛ 🛡️ {protect_status}"
    )

    inventory = data.get("inventory", [])
    keyboard = []
    if inventory:
        text += "\n\n💎 ꜰʟᴇx ᴄᴏʟʟᴇᴄᴛɪᴏɴ:"
        colors = ["primary", "success", "danger"]
        for i in range(0, len(inventory), 2):
            row = []
            item1_id = inventory[i]
            item1_name = SHOP_ITEMS.get(item1_id, {}).get("name", item1_id)
            row.append(InlineKeyboardButton(item1_name, callback_data="noop", style=colors[i % len(colors)]))
            
            if i + 1 < len(inventory):
                item2_id = inventory[i+1]
                item2_name = SHOP_ITEMS.get(item2_id, {}).get("name", item2_id)
                row.append(InlineKeyboardButton(item2_name, callback_data="noop", style=colors[(i+1) % len(colors)]))
            keyboard.append(row)
    
    reply_markup = InlineKeyboardMarkup(keyboard) if keyboard else None
    await update.message.reply_text(text, reply_markup=reply_markup)

async def noop_callback(update, context):
    query = update.callback_query
    await query.answer("💎 Flex Item!")

async def gift_cmd(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    if not update.message.reply_to_message:
        await update.message.reply_text("🎁 Reply karke: `/gift [item_id]`\nExample: `/gift cookie`", parse_mode="Markdown")
        return
    target = update.message.reply_to_message.from_user
    if target.id == user.id:
        await update.message.reply_text("😂 Apne aap ko gift?")
        return
    get_user(target.id)
    sender_data = db["users"][str(user.id)]
    if not context.args:
        await update.message.reply_text("❌ Item ID do! Example: `/gift cookie`", parse_mode="Markdown")
        return
    item_id = context.args[0].lower()
    if item_id not in SHOP_ITEMS:
        await update.message.reply_text("❌ Invalid item ID!")
        return
    if item_id not in sender_data.get("inventory", []):
        await update.message.reply_text("❌ Tumhare paas ye item nahi hai!")
        return
    
    sender_data["inventory"].remove(item_id)
    db["users"][str(target.id)].setdefault("inventory", []).append(item_id)
    save_db()
    await update.message.reply_text(f"🎁 Successfully gifted {SHOP_ITEMS[item_id]['name']} to {target.first_name}!")

async def sell_cmd(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    
    if not context.args:
        await update.message.reply_text("💰 Item ID do! Example: `/sell cookie`", parse_mode="Markdown")
        return
        
    item_id = context.args[0].lower()
    if item_id not in SHOP_ITEMS:
        await update.message.reply_text("❌ Invalid item ID!")
        return
        
    if item_id not in data.get("inventory", []):
        await update.message.reply_text("❌ Tumhare paas ye item nahi hai!")
        return
        
    original_price = SHOP_ITEMS[item_id]['price']
    sell_price = int(original_price * 0.9)
    
    old_bal = data["balance"]
    data["inventory"].remove(item_id)
    data["balance"] += sell_price
    new_bal = data["balance"]
    
    add_to_ledger(user.id, sell_price, "Sell", f"Sold {SHOP_ITEMS[item_id]['name']}", old_bal, new_bal)
    save_db()
    
    await update.message.reply_text(f"💰 Sold {SHOP_ITEMS[item_id]['name']} for ${sell_price:,} (10% less)!")

async def ledger_cmd(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    
    ledger = db["users"][str(user.id)].get("ledger", [])
    now = time.time()
    recent = [e for e in ledger if now - e["timestamp"] < 86400]
    
    if not recent:
        await update.message.reply_text("📒 Wallet History\n\nNo transactions in the last 24 hours.")
        return
        
    recent.sort(key=lambda x: x["timestamp"], reverse=True)
    
    total_in = sum(e["amount"] for e in recent if e["amount"] > 0)
    total_out = abs(sum(e["amount"] for e in recent if e["amount"] < 0))
    net = total_in - total_out
    
    text = (
        f"📒 WALLET HISTORY\n"
        f"👤 {user.first_name}\n"
        f"TODAY: +${total_in:,} IN | -${total_out:,} OUT | NET ${net:,}\n\n"
    )
    
    for entry in recent:
        amt = entry["amount"]
        sign = "+" if amt > 0 else "-"
        abs_amt = abs(amt)
        dt_obj = datetime.datetime.fromtimestamp(entry["timestamp"])
        dt_str = dt_obj.strftime('%d %b %I:%M %p').upper()
        
        text += f"{sign} ${abs_amt:,} • {entry['action']}\n"
        text += f"{entry['detail']}\n"
        text += f"${entry['old_balance']:,} → ${entry['new_balance']:,} • {dt_str}\n\n"
        
    await update.message.reply_text(text)

async def redeem_cmd(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    if not context.args:
        await update.message.reply_text("🎟️ Code do! Example: `/redeem nehaop`", parse_mode="Markdown")
        return
    code = context.args[0].lower()
    if not isinstance(db.get("redeem_codes"), dict): db["redeem_codes"] = {}
    if code not in db["redeem_codes"]:
        await update.message.reply_text("❌ Invalid code!")
        return
    code_data = db["redeem_codes"][code]
    if code_data["used"] >= code_data["limit"]:
        await update.message.reply_text("❌ Ye code ka limit khatam ho gaya hai!")
        return
    if user.id in code_data["users"]:
        await update.message.reply_text("❌ Tum ye code pehle hi use kar chuke ho!")
        return
    
    data = db["users"][str(user.id)]
    old_bal = data["balance"]
    data["balance"] += code_data["amount"]
    new_bal = data["balance"]
    code_data["used"] += 1
    code_data["users"].append(user.id)
    
    add_to_ledger(user.id, code_data["amount"], "Redeem", f"Redeemed code {code}", old_bal, new_bal)
    save_db()
    await update.message.reply_text(f"🎉 Redeem Successful!\n💰 Added ${code_data['amount']:,}\n💼 New Balance: ${data['balance']:,}")

async def daily(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    now = time.time()
    if now - data["daily_claimed"] < 86400:
        remaining = 86400 - (now - data["daily_claimed"])
        hours = int(remaining // 3600)
        minutes = int((remaining % 3600) // 60)
        await update.message.reply_text(f"❖ ⏰ {sc('daily already claimed')}\n\nNext: {hours}h {minutes}m")
        return
    reward = random.randint(50, 200)
    if premium_active(user.id):
        reward = int(reward * 1.5)
    old_bal = data["balance"]
    data["balance"] += reward
    new_bal = data["balance"]
    data["daily_claimed"] = now
    add_mission_progress(user.id, "daily", 1)

    add_to_ledger(user.id, reward, "Daily", "Daily reward", old_bal, new_bal)
    save_db()
    await update.message.reply_text(f"❖ 🎁 {sc('daily reward')}\n\n> ➕ {sc('received')}: {reward:,} 💰\n> 💼 {sc('total')}: {data['balance']:,}")

async def give(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    if not update.message.reply_to_message:
        await update.message.reply_text("💸 Reply karke: `/give 5k`", parse_mode="Markdown")
        return
    target = update.message.reply_to_message.from_user
    if target.id == user.id:
        await update.message.reply_text("😂 Apne aap ko?")
        return
    sender = db["users"][str(user.id)]
    amount = parse_amount(context.args, sender["balance"])
    if amount is None:
        await update.message.reply_text("❌ Sahi amount!", parse_mode="Markdown")
        return
    get_user(target.id)
    receiver = db["users"][str(target.id)]
    if sender["balance"] < amount:
        await update.message.reply_text(f"❌ {sc('insufficient coins')}!\n💰 {sender['balance']:,}")
        return
        
    old_bal_recv = receiver["balance"]
    sender["balance"] -= amount
    receiver["balance"] += amount
    
    add_to_ledger(target.id, amount, "Give Received", f"Received from {user.first_name}", old_bal_recv, receiver["balance"])
    save_db()
    await update.message.reply_text(f"❖ 💸 {sc('transfer complete')}\n\n> 👤 {user.first_name} → {target.first_name}\n> 💰 {sc('amount')}: {amount:,}")

async def loan(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    if not update.message.reply_to_message:
        await update.message.reply_text("🏦 Reply karke: `/loan 500`", parse_mode="Markdown")
        return
    target = update.message.reply_to_message.from_user
    if target.id == user.id:
        await update.message.reply_text("😂 Apne aap se loan?")
        return
    get_user(target.id)
    lender = db["users"][str(target.id)]
    if not isinstance(db.get("loans"), dict): db["loans"] = {}
    existing = db["loans"].get(str(user.id))
    if existing and isinstance(existing, dict) and existing.get("repay", 0) > 0:
        await update.message.reply_text(
            f"❌ Tumhara pehle se active loan hai!\n\n> 💰 Loan: {existing['amount']:,}\n> 📈 Repay: {existing['repay']:,}\n\nPehle `/repay` karo!",
            parse_mode="Markdown")
        return
    amount = parse_amount(context.args, None)
    if amount is None or amount <= 0:
        await update.message.reply_text("❌ Sahi amount! Jaise: `/loan 500`", parse_mode="Markdown")
        return
    if amount > 100_000_000:
        await update.message.reply_text("❌ Max 100M tak loan!")
        return
    if lender["balance"] < amount:
        await update.message.reply_text(
            f"❌ ⛔ Not enough coins!\n\n> 💰 {sc('their balance')}: {lender['balance']:,}\n> 🎯 {sc('need')}: {amount:,}",
            parse_mode="Markdown")
        return
    cid = f"loanc_{user.id}_{target.id}_{int(time.time())}"
    if not isinstance(db.get("loan_games"), dict): db["loan_games"] = {}
    db["loan_games"][cid] = {
        "requester_id": user.id, "requester_name": user.first_name,
        "requester_username": user.username,
        "lender_id": target.id, "lender_name": target.first_name,
        "lender_username": target.username,
        "amount": amount, "chat_id": update.effective_chat.id,
        "message_id": None, "phase": "pending",
    }
    save_db()
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("ACCEPT", callback_data=f"loanacc_{cid}", style="success"),
         InlineKeyboardButton("REJECT", callback_data=f"loanrej_{cid}", style="danger")]
    ])
    text = (
        f"🏦 {sc('loan request')} 💰\n━━━━━━━━━━━━━━━━━━━━\n\n"
        f"> 👤 {sc('borrower')}: {user.first_name}\n"
        f"> 💸 {sc('lender')}: {target.first_name}\n"
        f"> 💰 {sc('amount')}: {amount:,}\n"
        f"> 📈 {sc('repay')}: {int(amount * 1.1):,} (10%)\n"
        f"> ⏰ {sc('deadline')}: 48 hours\n\n"
        f"⚠️ {sc('48h baad 50% extra katega!')}\n\n"
        f"{sc('tap accept to lend')}! ✨"
    )
    msg = await update.message.reply_text(text, reply_markup=keyboard)
    db["loan_games"][cid]["message_id"] = msg.message_id
    save_db()

async def loan_accept_callback(update, context):
    query = update.callback_query
    await query.answer()
    cid = query.data.replace("loanacc_", "")
    if not isinstance(db.get("loan_games"), dict): db["loan_games"] = {}
    data = db["loan_games"].get(cid)
    if not data or data.get("phase") != "pending":
        await query.answer("Loan expire!", show_alert=True)
        return
    if query.from_user.id != data["lender_id"]:
        await query.answer(f"❌ Sirf {data['lender_name']} accept kar sakta hai!", show_alert=True)
        return
    get_user(data["lender_id"])
    lender = db["users"][str(data["lender_id"])]
    get_user(data["requester_id"])
    requester = db["users"][str(data["requester_id"])]
    if lender["balance"] < data["amount"]:
        await query.answer(f"⛔ Not enough coins!\n💰 {lender['balance']:,}", show_alert=True)
        return
        
    old_bal_borrower = requester["balance"]
    lender["balance"] -= data["amount"]
    requester["balance"] += data["amount"]
    new_bal_borrower = requester["balance"]
    
    add_to_ledger(data["requester_id"], data["amount"], "Loan Taken", f"Loan from {data['lender_name']}", old_bal_borrower, new_bal_borrower)
    
    repay_amount = int(data["amount"] * 1.1)
    db["loans"][str(data["requester_id"])] = {
        "amount": data["amount"], "repay": repay_amount,
        "lender_id": data["lender_id"], "lender_name": data["lender_name"],
        "lender_username": data.get("lender_username"),
        "requester_username": data.get("requester_username"),
        "taken_at": time.time(), "penalty_applied": False,
        "chat_id": data.get("chat_id"),
    }
    data["phase"] = "accepted"
    db["loan_games"][cid] = data
    save_db()
    try:
        await query.edit_message_text(
            f"🏦 {sc('loan approved')} ✅\n━━━━━━━━━━━━━━━━━━━━\n\n"
            f"> 👤 {sc('borrower')}: {data['requester_name']}\n"
            f"> 💸 {sc('lender')}: {data['lender_name']}\n"
            f"> 💰 {sc('loan amount')}: {data['amount']:,}\n"
            f"> 📈 {sc('repay')}: {repay_amount:,} (10%)\n"
            f"> ⏰ {sc('deadline')}: 48 hours\n\n"
            f"{sc('loan dediya')}! ✅",
            parse_mode="Markdown")
    except Exception as e:
        print(f"Loan accept edit error: {e}")
    db["loan_games"].pop(cid, None)
    save_db()

