async def loans_cmd(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    
    if not isinstance(db.get("loans"), dict): db["loans"] = {}
    
    active_loans = []
    now = time.time()
    for uid, loan_info in db["loans"].items():
        if not isinstance(loan_info, dict): continue
        if loan_info.get("repay", 0) <= 0: continue
        if uid != str(user.id): continue
        active_loans.append((uid, loan_info))
    
    if not active_loans:
        await update.message.reply_text(
            "❖ 🏦 " + sc("active loans") + "\n━━━━━━━━━━━━━━━━━━━━\n\n"
            "ᴛᴜᴍʜᴀʀᴀ ᴋᴏɪ ʟᴏᴀɴ ɴʜɪ ʜᴇ ✅",
            parse_mode="Markdown")
        return
    
    text = f"❖ 🏦 {sc('active loans')}\n━━━━━━━━━━━━━━━━━━━━\n\n"
    
    for uid, loan_info in active_loans:
        amount = loan_info.get("amount", 0)
        repay = loan_info.get("repay", 0)
        taken_at = loan_info.get("taken_at", now)
        hours_left = max(0, 48 - (now - taken_at) / 3600)
        
        lender_username = loan_info.get("lender_username")
        requester_username = loan_info.get("requester_username")
        
        lender_display = f"@{lender_username}" if lender_username else loan_info.get("lender_name", "Unknown")
        requester_display = f"@{requester_username}" if requester_username else loan_info.get("lender_name", "User")
        
        text += f"> 👤 {sc('borrower')}: {requester_display}\n"
        text += f"> 💰 {sc('loan amount')}: {amount:,}\n"
        text += f"> 📈 {sc('repay')}: {repay:,}\n"
        text += f"> 💸 {sc('lender')}: {lender_display}\n"
        text += f"> ⏰ {sc('time left')}: {int(hours_left)}h\n"
        text += "━━━━━━━━━━━━━━━━━━━━\n\n"
    
    text += f"> ⚠️ {sc('48 hours baad 50% extra kat jayega!')}\n"
    text += f"> ✅ {sc('repay karne ke liye /repay')}\n\n"
    text += f"🌟 Total: {len(active_loans)} active loans"
    
    await update.message.reply_text(text, parse_mode="Markdown")

async def repay(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    if not isinstance(db.get("loans"), dict): db["loans"] = {}
    loan_info = db["loans"].get(str(user.id))
    if not loan_info or (isinstance(loan_info, (int, float)) and loan_info <= 0):
        await update.message.reply_text("✅ Koi loan nahi!")
        return
    if isinstance(loan_info, (int, float)):
        repay_amount = int(loan_info)
        lender_id = None
    else:
        repay_amount = loan_info.get("repay", 0)
        lender_id = loan_info.get("lender_id")
        amount = loan_info.get("amount", repay_amount)
        taken_at = loan_info.get("taken_at", time.time())
        lender_name = loan_info.get("lender_name", "Unknown")
        lender_username = loan_info.get("lender_username")
        lender_display = f"@{lender_username}" if lender_username else lender_name
    if repay_amount <= 0:
        await update.message.reply_text("✅ Koi loan nahi!")
        return
    if context.args:
        if data["balance"] < repay_amount:
            await update.message.reply_text(f"❌ Coins kam!\n> 💰 Loan: {repay_amount:,}\n> 💼 Your balance: {data['balance']:,}")
            return
        old_bal = data["balance"]
        data["balance"] -= repay_amount
        new_bal = data["balance"]
        if lender_id:
            get_user(lender_id)
            db["users"][str(lender_id)]["balance"] += repay_amount
        db["loans"][str(user.id)] = 0
        
        add_to_ledger(user.id, -repay_amount, "Loan Repay", f"Repaid to {lender_name}", old_bal, new_bal)
        save_db()
        await update.message.reply_text(f"❖ ✅ {sc('loan repaid')}\n\n> 💸 {sc('paid')}: {repay_amount:,}\n> 💼 {sc('balance')}: {data['balance']:,}")
        return
    now = time.time()
    hours_left = max(0, 48 - (now - taken_at) / 3600)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("💰 REPAY NOW", callback_data=f"repaynow_{user.id}", style="success")]
    ])
    text = (
        f"❖ 🏦 {sc('your loan')}\n━━━━━━━━━━━━━━━━━━━━\n\n"
        f"> 💰 {sc('loan amount')}: {amount:,}\n"
        f"> 📈 {sc('repay amount')}: <code>{repay_amount}</code>\n"
        f"> 💸 {sc('lender')}: {lender_display}\n"
        f"> ⏰ {sc('time left')}: {int(hours_left)}h\n\n"
        f"⚠️ {sc('48h baad 50% extra katega!')}\n\n"
        f"💡 {sc('Upar wala number tap karke copy karo')}\n"
        f"{sc('Ya REPAY NOW dabao')}"
    )
    await update.message.reply_text(text, reply_markup=keyboard, parse_mode="HTML")

