async def protect(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    
    if data.get("is_dead", False):
        await update.message.reply_text("❌ Tum dead ho! Pehle /revive karo.")
        return
        
    if time.time() < data["protected_until"]:
        remaining = data["protected_until"] - time.time()
        hours = int(remaining // 3600)
        await update.message.reply_text(f"🛡️ Already protected! {hours}h baaki")
        return
    cost = 200
    if data["balance"] < cost:
        await update.message.reply_text(f"❌ {cost} coins chahiye!")
        return
    old_bal = data["balance"]
    data["balance"] -= cost
    new_bal = data["balance"]
    data["protected_until"] = time.time() + 86400
    
    add_to_ledger(user.id, -cost, "Protect", "Bought 24h protection", old_bal, new_bal)
    save_db()
    await update.message.reply_text(f"❖ 🛡️ {sc('protected')}\n⏰ 24h safe")

async def revive(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    
    target_id = user.id
    target_name = user.first_name
    is_self_revive = True
    
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
        target_id = target.id
        target_name = target.first_name
        is_self_revive = False
        
    get_user(target_id)
    target_data = db["users"][str(target_id)]
    
    if not target_data.get("is_dead", False):
        await update.message.reply_text(f"❌ {target_name} pehle se alive hai!")
        return
        
    cost = 500
    if data["balance"] < cost:
        await update.message.reply_text(f"❌ Tumhare paas {cost} coins nahi hain! Pehle kamao.")
        return
        
    old_bal = data["balance"]
    data["balance"] -= cost
    new_bal = data["balance"]
    target_data["is_dead"] = False
    target_data["deaths"] = 0
    
    add_to_ledger(user.id, -cost, "Revive", f"Revived {target_name}", old_bal, new_bal)
    save_db()
    
    if is_self_revive:
        await update.message.reply_text(f"❖ ✨ {sc('revived')}\n💰 Cost: {cost} coins\n💼 Your Balance: ${data['balance']:,}")
    else:
        await update.message.reply_text(f"❖ ✨ {target_name} ko revive kar diya!\n💰 Cost: {cost} coins (from your wallet)\n💼 Your Balance: ${data['balance']:,}")

async def send_action(update, context, action):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    if not update.message.reply_to_message:
        await update.message.reply_text("❌ Kisi ke message pe reply karke karo!")
        return
    target = update.message.reply_to_message.from_user
    if target.id == user.id:
        await update.message.reply_text("😂 Apne aap se?")
        return
    
    sticker_list = STICKER_PACKS.get(action, [])
    chosen_sticker = None
    if sticker_list:
        chosen_sticker = random.choice(sticker_list)
    
    normal_text = {
        "kiss":  f"💋 {user.first_name} ne {target.first_name} ko ᴋɪꜱꜱ ᴋɪʏᴀ! 😘💕",
        "hug":   f"🤗 {user.first_name} ne {target.first_name} ko ʜᴜɢ ᴋɪʏᴀ! 💕",
        "slap":  f"👋 {user.first_name} ne {target.first_name} ko ꜱʟᴀᴘ ᴋɪʏᴀ! 😤",
        "punch": f"👊 {user.first_name} ne {target.first_name} ko ᴘᴜɴᴄʜ ᴍᴀᴀʀᴀ! 💥",
    }
    
    if action == "punch" and sticker_list:
        punch_special_id = STICKER_PACKS["punch"][4]
        if chosen_sticker == punch_special_id:
            text = "😭 ʙʜᴀɪ ᴍᴀᴛ ᴋᴀʀʜᴀ ᴋʀ ᴀɪsᴇ ᴋᴀᴍ ɢᴀʀɪʙ ʟᴀɢᴛᴀ ʜᴇ 💔🥀"
        else:
            text = normal_text["punch"]
    else:
        text = normal_text.get(action, f"❖ {sc(action)}!")
    
    if chosen_sticker:
        try:
            await update.message.reply_sticker(chosen_sticker)
        except Exception as e:
            print(f"Sticker error: {e}")
    
    await update.message.reply_text(text)

