async def couples(update, context):
    if not update.message: return
    get_user(update.effective_user.id)
    users = list(db["users"].keys())
    if len(users) < 2:
        await update.message.reply_text("2 users chahiye!")
        return
    random.shuffle(users)
    pairs = []
    for i in range(0, min(10, len(users) - 1), 2):
        try:
            u1 = await context.bot.get_chat(int(users[i]))
            u2 = await context.bot.get_chat(int(users[i+1]))
            pairs.append(f"> 💕 {u1.first_name} ❤️ {u2.first_name}")
        except: pass
    if not pairs:
        await update.message.reply_text("Koi couples nahi!")
        return
    await update.message.reply_text(f"❖ 💑 {sc('random couples')}\n\n" + "\n".join(pairs))

