async def check_bet(update, context, user_data):
    bet = parse_amount(context.args, user_data["balance"])
    if bet is None:
        await update.message.reply_text(f"❌ Sahi amount!\n💡 `2k`, `5k`, `all`, `half`", parse_mode="Markdown")
        return None
    if user_data["balance"] < bet:
        await update.message.reply_text(f"❖ ❌ {sc('insufficient coins')}\n> 💰 {sc('balance')}: {user_data['balance']:,}\n> 🎯 {sc('need')}: {bet:,}")
        return None
    return bet

async def dice(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    bet = await check_bet(update, context, data)
    if bet is None: return
    
    old_bal = data["balance"]
    data["balance"] -= bet
    new_bal = data["balance"]
    add_to_ledger(user.id, -bet, "Dice Bet", f"DICE BET OF ${bet:,}", old_bal, new_bal)
    
    try:
        msg = await update.message.reply_dice(emoji="🎲")
        dice_value = msg.dice.value
    except Exception as e:
        print(f"Dice error: {e}")
        return
        
    if dice_value in [1, 2, 3]:
        data["losses"] = data.get("losses", 0) + 1
        result = f"🎲 ʀᴇsᴜʟᴛ: {bold(str(dice_value))}\n💀 ʏᴏᴜ ʟᴏsᴛ! -${bet:,}"
    else:
        old_bal2 = data["balance"]
        data["balance"] += bet * 2
        new_bal2 = data["balance"]
        data["wins"] = data.get("wins", 0) + 1
        result = f"🎲 ʀᴇsᴜʟᴛ: {bold(str(dice_value))}\n🎉 ʏᴏᴜ ᴡᴏɴ! +${bet*2:,}"
        add_to_ledger(user.id, bet*2, "Dice Win", f"WON DICE ROLL ({dice_value}) +${bet*2:,}", old_bal2, new_bal2)
        
    save_db()
    await asyncio.sleep(2)
    await update.message.reply_text(f"{result}\n\n💰 ${data['balance']:,}")

async def bowling(update, context):
    """Telegram bowling dice bet: pins 1-3 lose, 4-6 win."""
    if not update.message:
        return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    bet = await check_bet(update, context, data)
    if bet is None:
        return

    old_bal = data["balance"]
    data["balance"] -= bet
    add_to_ledger(user.id, -bet, "Bowling Bet", f"BOWLING BET ${bet:,}", old_bal, data["balance"])
    try:
        roll_msg = await update.message.reply_dice(emoji="🎳")
        value = roll_msg.dice.value
    except Exception as e:
        # Refund stake if Telegram cannot send the bowling animation.
        data["balance"] += bet
        save_db()
        print(f"Bowling dice error: {e}")
        await update.message.reply_text("🎳 Bowling abhi unavailable hai. Bet refund kar diya gaya.")
        return

    if value in (1, 2, 3):
        data["losses"] = data.get("losses", 0) + 1
        result = (f"🎳 𝐁𝐎𝐖𝐋𝐈𝐍𝐆 𝐑𝐄𝐒𝐔𝐋𝐓 🎳\n━━━━━━━━━━━━\n"
                  f"🎯 Pins: <b>{value}</b>\n💔 𝐘𝐨𝐮 𝐋𝐨𝐬𝐭!\n🔻 Bet: <b>${bet:,}</b>")
    else:
        prize = bet * 2
        before = data["balance"]
        data["balance"] += prize
        data["wins"] = data.get("wins", 0) + 1
        add_to_ledger(user.id, prize, "Bowling Win", f"BOWLING WIN (${prize:,}) value={value}", before, data["balance"])
        result = (f"🎳 𝐁𝐎𝐖𝐋𝐈𝐍𝐆 𝐑𝐄𝐒𝐔𝐋𝐓 🎳\n━━━━━━━━━━━━\n"
                  f"🎯 Pins: <b>{value}</b>\n🎉 𝐘𝐨𝐮 𝐖𝐨𝐧!\n💎 Prize: <b>+${prize:,}</b>")
    save_db()
    await asyncio.sleep(2)
    await update.message.reply_text(f"{result}\n━━━━━━━━━━━━\n👛 Wallet: <b>${data['balance']:,}</b>", parse_mode="HTML")


async def flip(update, context):
    if not update.message: return
    user = update.effective_user
    get_user(user.id)
    data = db["users"][str(user.id)]
    bet = await check_bet(update, context, data)
    if bet is None: return
    
    old_bal = data["balance"]
    if random.random() < 0.5:
        data["balance"] += bet
        new_bal = data["balance"]
        data["wins"] = data.get("wins", 0) + 1
        result = f"🎉 {sc('you won')}! +${bet:,}"
        add_to_ledger(user.id, bet, "Flip Win", f"Won coin flip", old_bal, new_bal)
    else:
        data["balance"] -= bet
        new_bal = data["balance"]
        data["losses"] = data.get("losses", 0) + 1
        result = f"💀 {sc('you lost')}! -${bet:,}"
        add_to_ledger(user.id, -bet, "Flip Loss", f"Lost coin flip", old_bal, new_bal)
        
    save_db()
    await update.message.reply_text(f"❖ 🪙 {sc('coin flip')}\n\n> {result}\n> 💰 ${data['balance']:,}")

