async def rps_move_callback(update, context):
    query = update.callback_query
    await query.answer()
    parts = query.data.rsplit("_", 1)
    cid_full = parts[0]
    move = parts[1]
    cid = cid_full.replace("rpsmv_", "")
    if move == "scissor": move = "scissors"
    data = db["rps_games"].get(cid)
    if not data or data.get("phase") != "pvp":
        await query.answer("Game expire!", show_alert=True)
        return
    user_id = query.from_user.id
    if user_id not in [data["challenger_id"], data.get("acceptor_id")]:
        await query.answer("❌ Not your game!\nNext time play! 🎮", show_alert=True)
        return
    is_challenger = (user_id == data["challenger_id"])
    if is_challenger:
        if data.get("choice1") is not None:
            await query.answer("Already choose!", show_alert=True)
            return
        data["choice1"] = move
    else:
        if data.get("choice2") is not None:
            await query.answer("Already choose!", show_alert=True)
            return
        data["choice2"] = move
    db["rps_games"][cid] = data
    save_db()
    await query.answer(f"✅ Saved: {move.upper()}", show_alert=False)
    if data.get("choice1") and data.get("choice2"):
        c1 = data["choice1"]
        c2 = data["choice2"]
        emoji_map = {"rock": "🪨", "paper": "📄", "scissors": "✂️"}
        if c1 == c2:
            get_user(data["challenger_id"])
            get_user(data["acceptor_id"])
            db["users"][str(data["challenger_id"])]["balance"] += data["bet"]
            db["users"][str(data["acceptor_id"])]["balance"] += data["bet"]
            save_db()
            result_text = (
                f"✊ {sc('rps result')}\n━━━━━━━━━━━━━━━━━━━━\n\n"
                f"> ᴘ𝟏: {emoji_map.get(c1, c1)}  🆚  ᴘ𝟐: {emoji_map.get(c2, c2)}\n\n"
                f"> 🤝 {sc('draw')}!\n> 💰 {sc('both refunded')}: ${data['bet']:,}"
            )
        else:
            p1_wins = (c1 == "rock" and c2 == "scissors") or \
                      (c1 == "paper" and c2 == "rock") or \
                      (c1 == "scissors" and c2 == "paper")
            if p1_wins:
                winner_id = data["challenger_id"]
                winner_num = "ᴘʟᴀʏᴇʀ 𝟏"
                winner_name = data["challenger_name"]
                loser_id = data["acceptor_id"]
            else:
                winner_id = data["acceptor_id"]
                winner_num = "ᴘʟᴀʏᴇʀ 𝟐"
                winner_name = data["acceptor_name"]
                loser_id = data["challenger_id"]
                
            get_user(winner_id)
            old_bal_win = db["users"][str(winner_id)]["balance"]
            db["users"][str(winner_id)]["balance"] += data["pot"]
            new_bal_win = db["users"][str(winner_id)]["balance"]
            db["users"][str(winner_id)]["wins"] = db["users"][str(winner_id)].get("wins", 0) + 1
            
            get_user(loser_id)
            db["users"][str(loser_id)]["losses"] = db["users"][str(loser_id)].get("losses", 0) + 1
            
            add_to_ledger(winner_id, data["pot"], "RPS Win", f"Won RPS vs {winner_name}", old_bal_win, new_bal_win)
            save_db()
            
            result_text = (
                f"✊ {sc('rps result')}\n━━━━━━━━━━━━━━━━━━━━\n\n"
                f"> ᴘ𝟏: {emoji_map.get(c1, c1)}  🆚  ᴘ𝟐: {emoji_map.get(c2, c2)}\n\n"
                f"> 🎉 {winner_num} ({winner_name}) {sc('wins')} ${data['pot']:,}!"
            )
        try:
            await context.bot.send_message(chat_id=data["chat_id"], text=result_text)
        except Exception as e:
            print(f"Result error: {e}")
        try:
            await context.bot.delete_message(chat_id=data["chat_id"], message_id=query.message.message_id)
        except Exception as e:
            print(f"Delete error: {e}")
        db["rps_games"].pop(cid, None)
        save_db()
    else:
        next_player = data["acceptor_id"] if is_challenger else data["challenger_id"]
        next_name = data["acceptor_name"] if is_challenger else data["challenger_name"]
        try:
            await context.bot.send_message(chat_id=data["chat_id"], text=f"🎯 {next_name}, {sc('now your turn')}!")
        except Exception as e:
            print(f"Turn notify error: {e}")

