async def broadcast_cmd(update, context):
    if not update.message: return
    if not is_admin(update.effective_user.id): return
    context.user_data["awaiting_broadcast"] = True
    await update.message.reply_text("📢 Message bhejo. /cancel")

async def ban_cmd(update, context):
    if not update.message: return
    if not is_admin(update.effective_user.id): return
    if not context.args:
        await update.message.reply_text("Use: `/ban USER_ID`", parse_mode="Markdown")
        return
    uid = context.args[0]
    if uid not in db["banned"]:
        db["banned"].append(uid)
        save_db()
    await update.message.reply_text(f"🚫 <code>{uid}</code> ban.", parse_mode="HTML")

async def unban_cmd(update, context):
    if not update.message: return
    if not is_admin(update.effective_user.id): return
    if not context.args: return
    uid = context.args[0]
    if uid in db["banned"]:
        db["banned"].remove(uid)
        save_db()
        await update.message.reply_text(f"✅ <code>{uid}</code> unban.", parse_mode="HTML")

async def addcoins_cmd(update, context):
    if not update.message: return
    if not is_admin(update.effective_user.id): return
    if len(context.args) < 2:
        await update.message.reply_text("Use: `/addcoins USER_ID 5k`", parse_mode="Markdown")
        return
    uid = context.args[0]
    amount = parse_amount([context.args[1]], None)
    if amount is None:
        await update.message.reply_text("❌ Sahi amount!", parse_mode="Markdown")
        return
    get_user(uid)
    db["users"][uid]["balance"] += amount
    save_db()
    await update.message.reply_text(f"✅ <code>{uid}</code> +{amount:,}", parse_mode="HTML")

async def cancel(update, context):
    if not update.message: return
    context.user_data.clear()
    await update.message.reply_text("❌ Cancel.")

