def get_local_reply(text):
    tl = text.lower().strip()
    for key in sorted(LOCAL_REPLIES.keys(), key=len, reverse=True):
        if key in tl:
            return random.choice(LOCAL_REPLIES[key])
    return None


async def track_channel_post(update, context):
    msg = update.channel_post
    if not msg or not msg.chat:
        return
    try:
        me = await context.bot.get_me()
        member = await context.bot.get_chat_member(msg.chat.id, me.id)
        if member.status in ("administrator", "creator"):
            db.setdefault("known_chats", {})[str(msg.chat.id)] = {"type": "channel", "title": msg.chat.title or "Channel"}
            save_db()
    except Exception as exc:
        logging.warning("Channel tracking skipped: %s", exc)

async def text_handler(update, context):
    try:
        if not update.message or not update.message.text: return
        user = update.effective_user
        get_user(user.id)
        if is_banned(user.id): return
        text = update.message.text.strip()
        if is_admin(user.id) and context.user_data.get("awaiting_add_admin"):
            try:
                aid = str(int(text.strip()))
                if int(aid) == OWNER_ID:
                    await update.message.reply_text("Owner already has full access.")
                else:
                    admins = db.setdefault("admins", [])
                    if aid not in admins:
                        admins.append(aid)
                        save_db()
                    await update.message.reply_text(f"✅ Admin added: <code>{aid}</code>", parse_mode="HTML")
            except ValueError:
                await update.message.reply_text("❌ Sirf numeric Telegram USER_ID bhejein.")
            context.user_data.pop("awaiting_add_admin", None)
            return
        if is_admin(user.id) and context.user_data.get("awaiting_remove_admin"):
            try:
                aid = str(int(text.strip()))
                if int(aid) == OWNER_ID:
                    await update.message.reply_text("❌ Owner ko remove nahi kar sakte.")
                else:
                    admins = db.setdefault("admins", [])
                    if aid in admins:
                        admins.remove(aid)
                        save_db()
                        await update.message.reply_text(f"✅ Admin removed: <code>{aid}</code>", parse_mode="HTML")
                    else:
                        await update.message.reply_text("Ye ID admin list mein nahi hai.")
            except ValueError:
                await update.message.reply_text("❌ Sirf numeric Telegram USER_ID bhejein.")
            context.user_data.pop("awaiting_remove_admin", None)
            return
        if update.effective_chat and update.effective_chat.type in ("group", "supergroup"):
            db.setdefault("known_chats", {})[str(update.effective_chat.id)] = {"type": update.effective_chat.type, "title": update.effective_chat.title or "Group"}
            save_db()
        if is_admin(user.id) and context.user_data.get("awaiting_premium_add"):
            try:
                uid, duration = text.split(maxsplit=1)
                u = get_user(uid)
                if duration.lower() in ("life", "lifetime", "-1"):
                    u["premium_until"] = -1
                else:
                    days = int(duration)
                    if days not in (14, 30): raise ValueError()
                    u["premium_until"] = max(time.time(), float(u.get("premium_until",0) or 0)) + days*86400
                save_db()
                await update.message.reply_text(f"✅ Premium updated for <code>{uid}</code>.", parse_mode="HTML")
            except Exception:
                await update.message.reply_text("❌ Format: USER_ID 14 | 30 | life")
            context.user_data.pop("awaiting_premium_add", None); return
        if is_admin(user.id) and context.user_data.get("awaiting_premium_remove"):
            uid = text.strip().lstrip("@").split()[0]
            u = get_user(uid); u["premium_until"] = 0; save_db()
            context.user_data.pop("awaiting_premium_remove", None)
            await update.message.reply_text(f"🗑️ Premium removed for <code>{uid}</code>.", parse_mode="HTML"); return
        if is_admin(user.id) and context.user_data.get("awaiting_chat_broadcast"):
            chats = db.setdefault("known_chats", {})
            sent = failed = 0
            for chat_id in list(chats):
                try:
                    await context.bot.send_message(chat_id=int(chat_id), text=f"📢 {text}")
                    sent += 1
                    await asyncio.sleep(0.08)
                except Exception:
                    failed += 1
            context.user_data.pop("awaiting_chat_broadcast", None)
            await update.message.reply_text(f"🌐 Chat broadcast done. Sent: {sent} · Failed: {failed}")
            return
        if await trivia_text_check(update, context): return
        if context.user_data.get("awaiting_broadcast") and is_admin(user.id):
            success = 0
            for uid in db["users"].keys():
                try:
                    await context.bot.send_message(int(uid), f"📢 Broadcast\n\n{text}")
                    success += 1
                    await asyncio.sleep(0.05)
                except: pass
            context.user_data.pop("awaiting_broadcast", None)
            await update.message.reply_text(f"✅ {success} users")
            return
        if context.user_data.get("awaiting_addcoins") and is_admin(user.id):
            try:
                uid, amount_str = text.split()
                amount = parse_amount([amount_str], None)
                if amount is None:
                    await update.message.reply_text("❌ Sahi amount!")
                    return
                get_user(uid)
                db["users"][uid]["balance"] += amount
                save_db()
                await update.message.reply_text(f"✅ <code>{uid}</code> +{amount:,}", parse_mode="HTML")
            except:
                await update.message.reply_text("❌ Format: <code>USER_ID AMOUNT</code>", parse_mode="HTML")
            context.user_data.pop("awaiting_addcoins", None)
            return
        if context.user_data.get("awaiting_removecoins") and is_admin(user.id):
            try:
                uid, amount_str = text.split()
                amount = parse_amount([amount_str], None)
                if amount is None:
                    await update.message.reply_text("❌ Sahi amount!")
                    return
                get_user(uid)
                db["users"][uid]["balance"] = max(0, db["users"][uid]["balance"] - amount)
                save_db()
                await update.message.reply_text(f"🔴 <code>{uid}</code> -{amount:,}", parse_mode="HTML")
            except:
                await update.message.reply_text("❌ Format: <code>USER_ID AMOUNT</code>", parse_mode="HTML")
            context.user_data.pop("awaiting_removecoins", None)
            return
        if context.user_data.get("awaiting_addall") and is_admin(user.id):
            try:
                amount = parse_amount([text], None)
                if amount is None:
                    await update.message.reply_text("❌ Sahi amount!")
                    return
                count = 0
                for uid in db["users"].keys():
                    db["users"][uid]["balance"] += amount
                    count += 1
                save_db()
                await update.message.reply_text(f"✅ {count} users +{amount:,}", parse_mode="HTML")
            except:
                await update.message.reply_text("❌ Sahi amount!")
            context.user_data.pop("awaiting_addall", None)
            return
        if context.user_data.get("awaiting_removeall") and is_admin(user.id):
            try:
                amount = parse_amount([text], None)
                if amount is None:
                    await update.message.reply_text("❌ Sahi amount!")
                    return
                count = 0
                for uid in db["users"].keys():
                    db["users"][uid]["balance"] = max(0, db["users"][uid]["balance"] - amount)
                    count += 1
                save_db()
                await update.message.reply_text(f"🔴 {count} users -{amount:,}", parse_mode="HTML")
            except:
                await update.message.reply_text("❌ Sahi amount!")
            context.user_data.pop("awaiting_removeall", None)
            return
        if context.user_data.get("awaiting_setall") and is_admin(user.id):
            try:
                amount = parse_amount([text], None)
                if amount is None:
                    await update.message.reply_text("❌ Sahi amount!")
                    return
                count = 0
                for uid in db["users"].keys():
                    db["users"][uid]["balance"] = amount
                    count += 1
                save_db()
                await update.message.reply_text(f"🔵 {count} users set to {amount:,}", parse_mode="HTML")
            except:
                await update.message.reply_text("❌ Sahi amount!")
            context.user_data.pop("awaiting_setall", None)
            return
        if context.user_data.get("awaiting_redeem_create") and is_admin(user.id):
            try:
                code, amount_str, limit_str = text.split()
                amount = parse_amount([amount_str], None)
                limit = int(limit_str)
                if amount is None or limit <= 0:
                    raise ValueError
                if not isinstance(db.get("redeem_codes"), dict): db["redeem_codes"] = {}
                db["redeem_codes"][code.lower()] = {"amount": amount, "limit": limit, "used": 0, "users": []}
                save_db()
                await update.message.reply_text(f"✅ Redeem code ban gaya!\nCode: <code>{code.lower()}</code>\nAmount: ${amount:,}\nLimit: {limit}", parse_mode="HTML")
            except:
                await update.message.reply_text("❌ Format: <code>code amount limit</code>\nExample: <code>nehaop 10000 10</code>", parse_mode="HTML")
            context.user_data.pop("awaiting_redeem_create", None)
            return
        if "guess_number" in context.user_data:
            await guess_handler(update, context)
            return
        tl = text.lower()
        owner_questions = ("owner" in tl and any(w in tl for w in ("who", "kon", "kaun", "tera", "tumhara", "your", "owner")))
        finx_mentions = any(name in tl for name in ("finxz", "finxzz", "finxzz"))
        if owner_questions:
            await update.message.reply_text(
                "👑💎 𝐌𝐞𝐫𝐞 𝐨𝐰𝐧𝐞𝐫 𝐅𝐢𝐧𝐱𝐳𝐳 𝐡𝐞𝐢𝐧! 💎👑\n"
                "🌸 Jinki wajah se main aaj yahan hoon. Mere ownerrrr sabse ache heeee! 🥹💖✨\n"
                "😘💞 Umaaaah! Unke liye lots of love, respect aur sparkling hearts! 💎🌷",
                reply_to_message_id=update.message.message_id)
            return
        if finx_mentions:
            await update.message.reply_text(
                "🙄😏💎 Mere owner ka naam aise nahi le sakta tu! 👑✨\n"
                "🌸 Sirf main hi apne Finxzz ka naam le sakti hoon, samjha? 😌💖🔐",
                reply_to_message_id=update.message.message_id)
            return

        should_reply = False
        if update.message.reply_to_message:
            replied_to = update.message.reply_to_message.from_user
            if replied_to and replied_to.id == context.bot.id:
                should_reply = True
        if update.message.entities:
            for entity in update.message.entities:
                if entity.type == "mention":
                    mt = text[entity.offset:entity.offset + entity.length]
                    if "neha" in mt.lower() or "nehq" in mt.lower():
                        should_reply = True
        if not should_reply: return
        reply = get_local_reply(text)
        if reply:
            await update.message.reply_text(reply)
    except Exception as e:
        print(f"Text handler error: {e}")

async def welcome_new_member(update, context):
    try:
        if not update.message or not update.message.new_chat_members:
            return
        for member in update.message.new_chat_members:
            if member.id == context.bot.id:
                await update.message.reply_text(welcome_text(member), reply_markup=start_keyboard())
                continue

            is_new_user = str(member.id) not in db.get("users", {})
            get_user(member.id)

            # Tell the owner when a genuinely new Telegram user joins a group.
            if is_new_user and not is_owner(member.id):
                await notify_owner_new_user(context, member, update.effective_chat)

            await update.message.reply_text(
                f"❖ 💙 {sc('welcome')} {member.first_name or 'User'}! 🎀"
            )
    except Exception as e:
        print(f"Welcome error: {e}")

async def post_init(app):
    await set_commands(app)
    asyncio.create_task(check_expired_loans(app))


