def premium_active(uid):
    u = get_user(uid)
    expiry = float(u.get("premium_until", 0) or 0)
    return expiry == -1 or expiry > time.time()

def premium_label(uid):
    return "👑 💎 PREMIUM" if premium_active(uid) else "👤 STANDARD"

def add_mission_progress(uid, key, amount=1):
    u = get_user(uid)
    today = int(time.time() // 86400)
    if int(u.get("mission_day", 0) or 0) != today:
        u["mission_day"] = today
        u["mission_progress"] = {}
        u["mission_claimed"] = []
    progress = u.setdefault("mission_progress", {})
    progress[key] = int(progress.get(key, 0)) + amount
    save_db()

