async def premium_callback(update, context):
    q = update.callback_query
    await q.answer()
    data = q.data
    if data in ("premium_open", "premium_back"):
        if data == "premium_back":
            restored = welcome_text(q.from_user)
            try:
                if q.message and (q.message.photo or q.message.video or q.message.animation):
                    await q.edit_message_caption(caption=restored, reply_markup=start_keyboard())
                else:
                    await q.edit_message_text(restored, reply_markup=start_keyboard())
            except Exception:
                await q.message.reply_text(restored, reply_markup=start_keyboard())
            return
        uid = q.from_user.id
        u = get_user(uid)
        exp = u.get("premium_until", 0) or 0
        status = "♾️ Lifetime Active" if exp == -1 else ("💎 Active" if exp and exp > time.time() else "🔓 Not Active")
        body = ("👑 <b>Premium Membership</b>\n━━━━━━━━━━━━━━━━━━\n"
                "<blockquote>💎 40% extra game win amount\n🏹 Successful rob: 10% bonus\n"
                "🎁 Daily reward: 50% extra\n✨ Premium profile badge\n\n"
                f"📌 Status: {status}</blockquote>\n\n<b>Plans</b>\n"
                "<blockquote>⭐ 14 Days — 15 Stars\n⭐ 30 Days — 25 Stars\n⭐ Lifetime — 100 Stars</blockquote>\n\n"
                "✅ Select a plan below · 🔒 Payment required")
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("👑 14 Days · 15 ⭐", callback_data="prem_plan_14", style="success"),
             InlineKeyboardButton("👑 30 Days · 25 ⭐", callback_data="prem_plan_30", style="success")],
            [InlineKeyboardButton("👑 Lifetime · 100 ⭐", callback_data="prem_plan_life", style="success")],
            [InlineKeyboardButton("🔙 Back", callback_data="premium_back", style="primary")]])
        try:
            if q.message and (q.message.photo or q.message.video or q.message.animation):
                await q.edit_message_caption(caption=body, parse_mode="HTML", reply_markup=kb)
            else:
                await q.edit_message_text(body, parse_mode="HTML", reply_markup=kb)
        except Exception:
            await q.message.reply_text(body, parse_mode="HTML", reply_markup=kb)
        return
    if data.startswith("prem_plan_"):
        plan = data.rsplit("_", 1)[1]
        plans = {"14": ("14 Days", 15), "30": ("30 Days", 25), "life": ("Lifetime", 100)}
        title, stars = plans[plan]
        context.user_data["premium_plan"] = plan
        await q.message.reply_text(
            f"⭐ <b>Neha Premium — {title}</b>\n\n"
            f"<blockquote>💳 Required: <b>{stars} Telegram Stars</b>\n"
            "🎁 @un3ck ko required Stars gift/payment bhejein.\n"
            "📸 Payment ke baad transaction/payment screenshot yahin bot ko bhejein.\n"
            "👑 Owner verify karke Approve ya Reject karega.</blockquote>\n\n"
            "⚠️ Payment complete karne ke baad hi proof bhejein.",
            parse_mode="HTML")
        return
    if data.startswith("prem_review_"):
        if not is_admin(q.from_user.id):
            await q.answer("Only owner can review.", show_alert=True)
            return
        _, _, decision, reqid = data.split("_", 3)
        req = db.setdefault("premium_requests", {}).get(reqid)
        if not req or req.get("status") != "pending":
            await q.answer("Request already handled.", show_alert=True)
            return
        uid = str(req["user_id"])
        if decision == "approve":
            u = get_user(uid)
            plan = req["plan"]
            if plan == "life":
                u["premium_until"] = -1
            else:
                days = int(plan)
                current = float(u.get("premium_until", 0) or 0)
                start = max(time.time(), current) if current > 0 else time.time()
                u["premium_until"] = start + days * 86400
            req["status"] = "approved"
            save_db()
            await context.bot.send_message(int(uid), "👑💎 Your Neha Premium membership is approved and active!")
            await q.edit_message_caption((q.message.caption or "") + "\n\n✅ APPROVED", reply_markup=None)
        else:
            req["status"] = "rejected"
            save_db()
            await context.bot.send_message(int(uid), "❌ Premium request rejected. Please contact @un3ck if you believe this is an error.")
            await q.edit_message_caption((q.message.caption or "") + "\n\n❌ REJECTED", reply_markup=None)

async def premium_proof_photo(update, context):
    if not update.message or not update.message.photo:
        return
    plan = context.user_data.get("premium_plan")
    if not plan:
        return
    user = update.effective_user
    reqid = f"{user.id}_{int(time.time())}"
    req = {"user_id": user.id, "plan": plan, "status": "pending", "created": time.time()}
    db.setdefault("premium_requests", {})[reqid] = req
    save_db()
    plan_title = {"14": "14 Days / 15 Stars", "30": "30 Days / 25 Stars", "life": "Lifetime / 100 Stars"}[plan]
    kb = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Approve", callback_data=f"prem_review_approve_{reqid}", style="success"),
        InlineKeyboardButton("❌ Reject", callback_data=f"prem_review_reject_{reqid}", style="danger")
    ]])
    caption = f"👑 Premium payment review\n👤 User: {html.escape(user.first_name or 'User')} (<code>{user.id}</code>)\n📦 Plan: {plan_title}\n🆔 Request: <code>{reqid}</code>"
    await context.bot.send_photo(chat_id=OWNER_ID, photo=update.message.photo[-1].file_id,
                                 caption=caption, parse_mode="HTML", reply_markup=kb)
    context.user_data.pop("premium_plan", None)
    await update.message.reply_text("📨 Payment proof Owner ko bhej diya gaya hai. Verification ka wait karein.")

async def trivia_cmd(update, context):
    chat_id = update.effective_chat.id
    if chat_id in TRIVIA_ACTIVE:
        await update.message.reply_text("🧠 Is chat mein Trivia question already active hai. Pehle answer dein!")
        return
    question, answers = random.choice(TRIVIA_QUESTIONS)
    game_token = f"{update.effective_user.id}:{time.time_ns()}"
    TRIVIA_ACTIVE[chat_id] = {
        "answers": [x.casefold() for x in answers],
        "asked_by": update.effective_user.id,
        "at": time.time(),
        "token": game_token,
        "message_id": None,
    }
    sent = await update.message.reply_text(
        f"🧠 <b>NEHA TRIVIA</b>\n\n❓ {question}\n\n💰 <b>REWARD: $750</b>\n✍️ TYPE THE ANSWER IN CHAT.\n⏳ <i>Time limit: 60 seconds</i>",
        parse_mode="HTML")
    TRIVIA_ACTIVE[chat_id]["message_id"] = sent.message_id
    async def expire_trivia():
        await asyncio.sleep(60)
        active = TRIVIA_ACTIVE.get(chat_id)
        if active and active.get("token") == game_token:
            TRIVIA_ACTIVE.pop(chat_id, None)
            try:
                await context.bot.delete_message(chat_id=chat_id, message_id=sent.message_id)
            except Exception as exc:
                print(f"Trivia expiry delete error: {exc}")
    asyncio.create_task(expire_trivia())

async def trivia_text_check(update, context):
    if not update.message or not update.message.text:
        return False
    chat_id = update.effective_chat.id
    game = TRIVIA_ACTIVE.get(chat_id)
    if not game:
        return False
    answer = re.sub(r"\s+", " ", update.message.text.strip().casefold())
    if answer not in game["answers"]:
        return False
    winner = update.effective_user
    u = get_user(winner.id)
    reward = 750
    if premium_active(winner.id):
        reward = int(reward * 1.4)
    old = int(u.get("balance", 0))
    u["balance"] = old + reward
    u["wins"] = int(u.get("wins", 0)) + 1
    add_mission_progress(winner.id, "trivia", 1)
    add_mission_progress(winner.id, "wins", 1)
    add_to_ledger(winner.id, reward, "Trivia", "Correct trivia answer", old, u["balance"])
    TRIVIA_ACTIVE.pop(chat_id, None)
    db.setdefault("trivia_stats", {}).setdefault(str(winner.id), 0)
    db["trivia_stats"][str(winner.id)] += 1
    save_db()
    await update.message.reply_text(f"🎉 Correct, {html.escape(winner.first_name or 'Player')}!\n👑 Reward: ${reward:,}\n💰 Wallet: ${u['balance']:,}", parse_mode="HTML")
    return True

async def work_cmd(update, context):
    u = get_user(update.effective_user.id)
    now = time.time()
    wait = 3600 - (now - float(u.get("work_at", 0) or 0))
    if wait > 0:
        await update.message.reply_text(f"💼 Work cooldown: {int(wait//60)}m {int(wait%60)}s")
        return
    amount = random.randint(150, 650)
    if premium_active(update.effective_user.id):
        amount = int(amount * 1.5)
    old = int(u["balance"])
    u["balance"] = old + amount
    u["work_at"] = now
    add_to_ledger(update.effective_user.id, amount, "Work", "Hourly job", old, u["balance"])
    save_db()
    await update.message.reply_text(f"💼 You worked as {random.choice(['Developer','Detective','Designer','Banker','Business Owner'])}!\n💰 Earned: ${amount:,}")

async def spin_cmd(update, context):
    u = get_user(update.effective_user.id)
    now = time.time()
    wait = 86400 - (now - float(u.get("spin_at", 0) or 0))
    if wait > 0:
        await update.message.reply_text(f"🎡 Next free spin in {int(wait//3600)}h {int((wait%3600)//60)}m")
        return
    reward = random.choice([50, 100, 250, 500, 1000, 2500, 5000])
    old = int(u["balance"])
    u["balance"] = old + reward
    u["spin_at"] = now
    add_to_ledger(update.effective_user.id, reward, "Lucky Spin", "Daily spin", old, u["balance"])
    save_db()
    await update.message.reply_text(f"🎡 <b>NEHA LUCKY SPIN</b>\n🎁 You won ${reward:,}!\n💰 Wallet: ${u['balance']:,}", parse_mode="HTML")

async def mission_cmd(update, context):
    uid = update.effective_user.id
    u = get_user(uid)
    today = int(time.time() // 86400)
    if int(u.get("mission_day", 0) or 0) != today:
        u["mission_day"] = today
        u["mission_progress"] = {}
        u["mission_claimed"] = []
    p = u.setdefault("mission_progress", {})
    claimed = set(u.setdefault("mission_claimed", []))
    missions = [
        ("daily", "🎁 Claim /daily", 1, 500),
        ("wins", "🎮 Win 3 games", 3, 1000),
        ("trivia", "🧠 Answer 5 Trivia questions", 5, 750),
    ]
    rows = []
    total = 0
    for key, label, goal, prize in missions:
        count = min(goal, int(p.get(key, 0)))
        done = count >= goal
        if done and key not in claimed:
            rows.append(f"✅ {label} — {count}/{goal} — ${prize:,} (claim via /missionclaim)")
        elif key in claimed:
            rows.append(f"🎁 {label} — Reward claimed")
        else:
            rows.append(f"⏳ {label} — {count}/{goal} — ${prize:,}")
        total += prize
    save_db()
    await update.message.reply_text("🎯 <b>DAILY MISSIONS</b>\n\n" + "\n".join(rows) + f"\n\n🏆 Total possible: ${total:,}\nUse /missionclaim to collect completed rewards.", parse_mode="HTML")

async def missionclaim_cmd(update, context):
    uid = update.effective_user.id
    u = get_user(uid)
    today = int(time.time() // 86400)
    if int(u.get("mission_day", 0) or 0) != today:
        u["mission_day"] = today
        u["mission_progress"] = {}
        u["mission_claimed"] = []
    p = u.setdefault("mission_progress", {})
    claimed = set(u.setdefault("mission_claimed", []))
    prizes = {"daily": (1, 500), "wins": (3, 1000), "trivia": (5, 750)}
    reward = 0
    for key, (goal, prize) in prizes.items():
        if int(p.get(key, 0)) >= goal and key not in claimed:
            reward += int(prize * (1.5 if premium_active(uid) else 1))
            claimed.add(key)
    if not reward:
        await update.message.reply_text("🎯 Abhi koi unclaimed mission complete nahi hai. /mission check karein.")
        return
    old = int(u["balance"])
    u["balance"] = old + reward
    u["mission_claimed"] = list(claimed)
    add_to_ledger(uid, reward, "Missions", "Daily mission rewards", old, u["balance"])
    save_db()
    await update.message.reply_text(f"🎉 Missions claimed!\n💰 Bonus: ${reward:,}\n👛 Wallet: ${u['balance']:,}")

async def profile_cmd(update, context):
    if not update.message:
        return
    user = update.effective_user
    u = get_user(user.id)
    rank = get_rank(user.id)
    exp = float(u.get("premium_until", 0) or 0)
    if exp == -1:
        premium = "♾️ Lifetime VIP"
    elif exp > time.time():
        premium = "💎 VIP Active until " + datetime.datetime.fromtimestamp(exp).strftime("%d %b %Y")
    else:
        premium = "🔹 Standard Member"

    display_name = html.escape(user.full_name or "Player")
    vip_line = "👑 <b>VIP PLAYER</b>" if premium_active(user.id) else "👤 <b>STANDARD PLAYER</b>"
    caption = (
        "👑 <b>NEHA PLAYER PROFILE</b>\n"
        "━━━━━━━━━━━━\n"
        f"{vip_line}\n"
        f"👤 <b>{display_name}</b>\n"
        f"🆔 <code>{user.id}</code>\n"
        f"💎 {html.escape(premium)}\n"
        "━━━━━━━━━━━━\n"
        f"👛 Wallet: <b>${int(u.get('balance', 0)):,}</b>\n"
        f"🏦 Bank: <b>${int(u.get('bank', 0)):,}</b>\n"
        f"🏆 Rank: <b>#{rank}</b>\n"
        f"🎮 Wins: <b>{int(u.get('wins', 0))}</b>\n"
        f"⚔️ Kills: <b>{int(u.get('kills', 0))}</b>\n"
        f"🧺 Flex Items: <b>{len(u.get('inventory', []) or [])}</b>"
    )
    caption = _premiumize_html(caption)

    inventory = u.get("inventory", []) or []
    keyboard = []
    colors = ["primary", "success", "danger"]
    for i in range(0, len(inventory), 2):
        row = []
        for j, item_id in enumerate(inventory[i:i+2]):
            item_name = SHOP_ITEMS.get(item_id, {}).get("name", str(item_id))
            row.append(InlineKeyboardButton(str(item_name)[:60], callback_data="noop", style=colors[(i+j) % len(colors)]))
        keyboard.append(row)
    reply_markup = InlineKeyboardMarkup(keyboard) if keyboard else None

    # Send the user's actual Telegram profile photo with the profile caption.
    try:
        photos = await context.bot.get_user_profile_photos(user.id, limit=1)
        if photos.total_count and photos.photos and photos.photos[0]:
            photo_file_id = photos.photos[0][-1].file_id
            await update.message.reply_photo(
                photo=photo_file_id, caption=caption, parse_mode="HTML", reply_markup=reply_markup
            )
            return
    except Exception as e:
        logging.warning("Could not fetch profile photo for %s: %s", user.id, e)

    # No public profile photo or fetch unavailable: retain all profile data as text.
    await update.message.reply_text(caption, parse_mode="HTML", reply_markup=reply_markup)

